properties.query:
// Groups with at least one event ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | extend Ingested = ingestion_time() | where Ingested <= now();
let SuricataNew = Suricata_CL | extend Ingested = ingestion_time() | where Ingested <= now();
union
    (SuricataNew | where signature startswith "ET CINS " or signature startswith "ET DROP " or signature startswith "ET COMPROMISED " | extend event_type = "suricata_reputation"),
    (CowrieNew | where eventid =~ "cowrie.login.success" | extend event_type = "cowrie_login_success")
| summarize event_type_count = dcount(event_type), new_events = countif(Ingested > ago(15m)) by bin(TimeGenerated, 1h), src_ip
| where event_type_count >= 2
| where new_events > 0
// One alert per source IP
| summarize Matches = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by src_ip
